  payload = coerce(inner) || {};
  if (!verb && obj._raw) { verb = obj._raw; }
  if ((!payload || Object.keys(payload).length === 0) && (obj.personId || obj.assignmentId || obj.worker || obj.newManager || obj.effectiveDate || obj.updateType || obj.formContext)) { payload = obj; }
