}

// hidden system field round-trips the write keys as a JSON string -> unwrap it
if (payload && payload.formContext) {
  var fc = coerce(payload.formContext);
  if (fc && typeof fc === 'object') {
    payload.personId = payload.personId || fc.personId;
    payload.periodOfServiceId = payload.periodOfServiceId || fc.periodOfServiceId;
    payload.assignmentId = payload.assignmentId || fc.assignmentId;
