// verb may itself be a quoted invoke like startReportingChange or submitReportingChange
var v = String(verb || '').trim();
if (v.indexOf('submitReportingChange') >= 0) v = 'submitReportingChange';
else if (v.indexOf('startReportingChange') >= 0) v = 'startReportingChange';
else if (v.indexOf('confirmWrite') >= 0) v = 'confirmWrite';
else if (v.indexOf('changeMgr') >= 0) v = 'changeMgr';
