var ctxNode = $context.$nodes.BUILD_MANAGER_UPDATE_CONTEXT;
var ctx = (ctxNode && ctxNode.$output && ctxNode.$output.result) ? ctxNode.$output.result : new Object();
var req = ctx.request || new Object();
var today = String($context.$system.$currentDate || '');

var hard = [];
var soft = [];

var asString = (v) => (v===null||v===undefined)?'':String(v).trim();

// carry through any errors the context resolver already raised
if (ctx.hasError === true && Array.isArray(ctx.errors)) { for (var i=0;i<ctx.errors.length;i++) hard.push(ctx.errors[i]); }

// HARD 1: self-manager (new manager person must differ from worker person)
var workerPN = asString(ctx.targetWorkerPersonNumber);
var newMgrPN = asString(ctx.newManagerPersonNumber);
if (workerPN && newMgrPN && workerPN === newMgrPN) {
  hard.push('A worker cannot be their own manager. The proposed manager is the same person as the worker.');
}

// HARD 2: direct supervisor cycle (new manager already reports to this worker)
// the proposed manager assignment number derives from the manager person; the worker currently appears
// as the proposed manager's own line manager -> cycle. We check the new manager assignment number against
// the worker assignment number.
var workerAsgNum = asString(ctx.targetAssignmentNumber);
var newMgrAsgNum = asString(ctx.newManagerAssignmentNumber);
if (workerAsgNum && newMgrAsgNum && workerAsgNum === newMgrAsgNum) {
  hard.push('The proposed manager assignment is the same as the worker assignment, which would create a direct reporting cycle.');
}

// HARD 3: effective date floor (>= today minus 30 day retro window)
var eff = asString(req.effectiveDate);
if (!eff) {
  hard.push('An effective date is required.');
} else {
  // YYYY-MM-DD lexical compare is valid for ISO dates; compute 30-day retro floor
  var d = new Date(eff + 'T00:00:00Z');
  var t = new Date(today + 'T00:00:00Z');
  if (isFinite(d.getTime()) && isFinite(t.getTime())) {
    var diffDays = Math.round((t.getTime() - d.getTime()) / 86400000);
    if (diffDays > 30) hard.push('The effective date ' + eff + ' is more than 30 days in the past. Choose a date within the last 30 days or a future date.');
  }
}

// HARD 4: manager active on the effective date — context already flags inactive existing records;
// also require the new manager to have been resolved to an assignment number
if (!newMgrAsgNum) hard.push('The proposed manager could not be resolved to an active assignment.');

// SOFT 1: cross business unit / legal employer (compare via update items if present)
