}

var cobj = new Object();
cobj.action = 'confirmWrite';
cobj.workerPersonNumber = ctx.targetWorkerPersonNumber || null;
cobj.newManagerPersonNumber = ctx.newManagerPersonNumber || null;
cobj.updateType = (req.updateType || 'LINE_MANAGER');
