var decision = hard.length > 0 ? 'REFUSE' : 'PROCEED';
var vout = new Object();
vout.decision = decision;
vout.hardFailures = hard;
vout.softWarnings = soft;
vout.workerName = ctx.targetWorkerName || null;
vout.newManagerName = ctx.newManagerName || null;
vout.effectiveDate = req.effectiveDate || null;
vout.confirmCommand = confirmCommand;
var curName = '';
for (var ci = 0; ci < items.length; ci++) {
  var cit = items[ci];
  if (!cit) { continue; }
  var nm = asString(cit.currentManagerName) || asString(cit.currentManagerAssignmentNumber);
  if (nm) { curName = nm; break; }
}
var ccard = new Object();
ccard.title = 'Confirm Line Manager Change';
ccard.patternId = 'cardWidget';
ccard.description = 'Review the proposed change before it is written.';
var cprops2 = new Object();
cprops2.subject = 'Confirm Line Manager Change';
var NL2 = String.fromCharCode(10);
var ARROW = String.fromCharCode(8594);
var csum = 'Worker: ' + (asString(ctx.targetWorkerName) || 'Not resolved');
csum = csum + NL2 + 'Line Manager: ' + (curName || 'Not currently assigned') + ' ' + ARROW + ' ' + (asString(ctx.newManagerName) || 'Proposed manager');
csum = csum + NL2 + 'Effective Date: ' + (asString(req.effectiveDate) || 'Not set');
for (var si = 0; si < soft.length; si++) { csum = csum + NL2 + 'Caution: ' + soft[si]; }
cprops2.summary = csum;
cprops2.badgeText = 'Needs confirmation';
cprops2.variant = 'warning';
var clink = new Object();
clink.text = 'Confirm Change';
clink.action = confirmCommand;
cprops2.link = clink;
ccard.properties = cprops2;
vout.confirmCard = ccard;
return vout;

