var msg = '';
try { msg = String($context.$system.$inputMessage || '').trim(); } catch (e) { msg = ''; }

var lower = msg.toLowerCase();

// Tokens that signal a CONVERSATIONAL change request (must fall through to PARSE), not a bare lookup.
var changeWords = ['manager','line','project','reward','time card','timecard','timesheet','update','change',
                   'set ','assign','move','transfer','effective','confirm','yes','proceed','go ahead',
                   'approve','approved','do it','to ','new '];
var hasChangeWord = false;
for (var i = 0; i < changeWords.length; i++) {
  if (lower.indexOf(changeWords[i]) >= 0) { hasChangeWord = true; break; }
}

// Count word-ish tokens (a bare lookup is a single number, or a short 1-3 word name).
var parts = msg.split(/\s+/).filter(s => s.length > 0);

// A pure person number: all digits (allow a leading zero-padded id).
var isPureNumber = /^[0-9]{1,15}$/.test(msg);

// A short plain name: 1-3 alphabetic tokens, no digits, no change words.
var isPlainName = parts.length >= 1 && parts.length <= 3 &&
                  /^[A-Za-z][A-Za-z'.\-]*(\s+[A-Za-z][A-Za-z'.\-]*){0,2}$/.test(msg);

var isBareWorker = (isPureNumber || (isPlainName && !hasChangeWord)) && !hasChangeWord;
// numbers always win even if a stray change word matched a substring (defensive)
if (isPureNumber) isBareWorker = true;

return { isBareWorker: isBareWorker, message: msg };

